package dsl

// Engine holds the enumeration for all available engines. These are
// auto-generated by the compiler depending on what engines are
// available.
type Engine int32

// Camera holds the enumeration for all available cameras. These are
// auto-generated by the compiler depending on what cameras are
// available.
type Camera int32

// Squadmate holds the enumeration for all available squadmates. These
// are auto-generated by the compiler depending on which vehicles are
// collaborating on the mission.
type Squadmate int32

// Role holds the enumeration for all available roles. These are auto-
// generated by the compiler depending on which roles are active in the
// mission.
type Role int32
